DIRECTIONS={'familiar_fraction':'max','D_A':'max','D_B':'max','A_to_B':'max','B_to_A':'max','sustained_cost':'max','C_ce':'min','C_accuracy':'max','Mixed_ce':'min','Mixed_accuracy':'max'}

def result_view(r):
    if not r:return None
    view={k:v for k,v in r.items() if k not in ['individual_results','matched_control_results','cohort','coverage']}
    rows=r.get('individual_results',[])
    if rows:
        fields=['own_A','cross_A','own_B','cross_B','net_A','net_B','D_A','D_B','familiar_ce','C_ce','C_correct']
        view['per_seed_task_means']=clean(pd.DataFrame(rows).groupby('seed')[fields].mean().reset_index().to_dict('records'))
        failures=[x for x in rows if not x['C_useful']];example=max(failures,key=lambda x:x['C_ce']) if failures else next((x for x in rows if not x['original_early_phenotype']),rows[0]);view['diagnostic_example']=example;view['example_scope']='deterministic development failure for criticism only; all cases remain in stored evidence'
    else:view['coverage']=r.get('coverage')
    return view

def leaf_changes(a,b,prefix=''):
    changed=[]
    for k in a:
        key=prefix+k
        if isinstance(a[k],dict):changed+=leaf_changes(a[k],b[k],key+'.')
        elif a[k]!=b[k]:changed.append(key)
    return changed

def control_config(store,p):
    match=p['matched_control']
    if match=='baseline':return copy.deepcopy(DEFAULT)
    if isinstance(match,dict) and 'config' in match:return validate(match['config'])
    node=next((r for r in store.nodes() if r['id']==match),None)
    if not node:raise ValueError('Unregistered matched control')
    return validate(json.loads(node['proposal'])['config'])

def admit(store,p):
    validate_proposal(p);validate(p['config']);control=control_config(store,p);diff=leaf_changes(control,p['config'])
    if not diff:raise ValueError('No experimental intervention')
    if len(diff)>1 and not p.get('complex_change_justification'):raise ValueError('One principal mechanism or explicit complex-change justification required')
    if not p.get('novelty_justification'):raise ValueError('Explain novelty against the supplied history, including inconclusive predecessors')
    if p.get('arbitrary_python'):raise ValueError('Arbitrary code quarantined; operator extension requires versioned review/tests')
    primary=p.get('ablation_primary',dict(metric='C_ce',direction='min'));expected={'C_ce':'min','Mixed_ce':'min','D_A':'max','D_B':'max','A_to_B':'max','B_to_A':'max','sustained_cost':'max'}
    if primary.get('metric') not in expected or primary.get('direction')!=expected[primary['metric']]:raise ValueError('Preregister a valid behavioral ablation metric/direction')
    code=read(PACKAGE/'audit/evaluator_seal.json')['runner_hash'];store.register(p,code)
    pending=store.get('pending') or {}
    if pending.get('call_id'):store.db.execute('INSERT INTO call_links VALUES(?,?)',(pending['call_id'],p['id']))
    dest=store.directory/'candidates'/p['id'];write(dest/'proposal.json',p,True);write(dest/'config.json',p['config'],True);write(dest/'control_config.json',control,True)
    # Executable adapter is generated by trusted infrastructure, not imported
    # from an agent's arbitrary output. Allfive interface functions are exposed.
    wrapper='from research_search.runners.candidate import build_model, build_training_schedule, run_pretraining, run_target_learning, export_predictions\n'
    (dest/'candidate.py').write_text(wrapper)
    write(dest/'manifest.json',dict(candidate_id=p['id'],parent_candidate=p.get('parent_candidate'),hypothesis=p['hypothesis'],changed_mechanism=p['mechanism'],code_sha=sha(dest/'candidate.py'),runner_hash=code,config_hash=fingerprint(p['config']),training_objective='native meanCE+.2 detached-confidence execution; jointclip1; ordinary Reptile',pretraining_episodes=p['config']['prior']['episodes'],actual_optimizer_steps=None,exposure='pending',evaluation_seeds='development bank only',runtime=None,token_usage='see shared calls ledger, never double-counted',checkpoint_paths=[],evaluation_results='pending',changed_fields=diff),True)
    return p

def manifest_snapshot(store,p,ids,competence_ids,stage):
    jobs=set(ids+competence_ids)
    for id in list(jobs):
        row=store.db.execute('SELECT payload FROM jobs WHERE id=?',(id,)).fetchone();payload=json.loads(row['payload'])
        if payload.get('prior_file'):jobs.add(Path(payload['prior_file']).parent.name)
    records=[];new=0;reused=0;cpu=0.;checkpoints=[]
    for id in sorted(jobs):
        row=store.db.execute('SELECT * FROM jobs WHERE id=?',(id,)).fetchone();count=store.db.execute('SELECT count(*) FROM steps WHERE job=?',(id,)).fetchone()[0];owned=row['candidate']==p['id'];new+=count if owned else 0;reused+=0 if owned else count;payload=json.loads(row['payload']);cost=store.db.execute('SELECT coalesce(sum(actual),0) FROM cpu WHERE id LIKE ?',(f'job-{id}-%',)).fetchone()[0];cpu+=cost;kind=payload['kind'];records.append(dict(job=id,kind=kind,status=row['status'],optimizer_attempts=count,exact_reuse=not owned,CPU_seconds=cost))
        for name in ['states.pt','pretrained.pt']:
            f=store.directory/'jobs'/id/name
            if f.exists():checkpoints.append(dict(path=str(f.relative_to(store.directory)),sha256=sha(f)))
    usage=store.db.execute('SELECT coalesce(sum(c.total),0),coalesce(sum(c.cached),0) FROM calls c JOIN call_links l ON c.id=l.call WHERE l.candidate=?',(p['id'],)).fetchone()
    record=dict(candidate_id=p['id'],stage=stage,parent_candidate=p.get('parent_candidate'),hypothesis=p['hypothesis'],mechanism=p['mechanism'],source_code_hash=read(PACKAGE/'audit/evaluator_seal.json')['runner_hash'],configuration_hash=fingerprint(p['config']),training_objective='native CE+.2 detached execution; ordinary Reptile; joint clip1',pretraining_episodes=p['config']['prior']['episodes'],actual_new_optimizer_attempts=new,exact_reused_optimizer_attempts=reused,sequence_prediction_exposure=records,initialization_and_evaluation_seeds=sorted({json.loads(store.db.execute('SELECT payload FROM jobs WHERE id=?',(id,)).fetchone()[0])['seed'] for id in ids}),CPU_seconds_including_reused_jobs=cpu,reported_model_tokens=usage[0],cached_input_tokens=usage[1],token_scope='calls linked to this candidate so far; unassigned/setup costs stay in shared campaign ledger',checkpoints=checkpoints,evaluation_results=f'{stage}.json',all_target_practice_AB_only=True,NoContext_not_a_gate=True)
    write(store.directory/'candidates'/p['id']/f'manifest_{stage}.json',record,True)

def context(store):
    # Explicit allowlist: never pass confirmation data, private paths, requests,
    # raw SQLite records or confirmation outcomes to a research agent.
    results=[json.loads(r['value']) for r in store.db.execute('SELECT value FROM results')]
    visible=agent_view(results)[-1:];compact=[result_view(r) for r in visible]
    history=[{k:r.get(k) for k in ['program','status','mechanism','claim']}|dict(numerical_source=r.get('numerical_sources',[None])[0]) for r in read(PACKAGE/'history/TESTED_HYPOTHESES.json')]
    screen=[{k:r.get(k) for k in ['candidate','mechanism','status','pilot_classifications','promotion_eligible','C_ce','C_correct','original_early']} for r in read(PACKAGE/'history/SCREEN_HYPOTHESES_v2.json')]
    return dict(goal=(PACKAGE/'RESEARCH_GOAL.md').read_text(),history=history,screen_history=screen,open_hypotheses=read(PACKAGE/'history/OPEN_HYPOTHESES.json'),development_results=compact,search_space=read(PACKAGE/'config/search_space.yaml'),budgets=store.state(),candidate_configs=[dict(id=r['id'],config=json.loads(r['proposal'])['config'],status=r['status']) for r in store.nodes()[-4:]])

def _enqueue(store,id,candidate,payload):
    old=store.db.execute('SELECT * FROM jobs WHERE id=?',(id,)).fetchone()
    if old:
        # Exact scientific aliases reuse the originally registered complete
        # prior payload; target-only changes do not alter prior training.
        if old['status'] in ['failed','uncertain']:raise RuntimeError('Failed/uncertain cached branch cannot be silently rerun: '+id)
        return old['status']
    enqueue(store,id,candidate,payload);return 'queued'

def ensure_jobs(store,candidate,config,seeds,phase='development'):
    bank=read(store.directory/('development.json' if phase=='development' else 'sealed/confirmation.json'));sealed=read(store.directory/'sealed/confirmation.json');dev=read(store.directory/'development.json');forbidden=[t['path'] for t in dev['tasks']+sealed['tasks']];identity=read(PACKAGE/'audit/evaluator_seal.json')['runner_hash'];target_ids=[];competence_ids=[]
    for seed in seeds:
        key=fingerprint(dict(model=config['model'],prior=config['prior'],seed=seed,development_sha=sha(store.directory/'development.json'),confirmation_commitment=sha(store.directory/'sealed/confirmation.json')))[:24];prior='prior-'+key;tasks_path=store.directory/'task_libraries'/f'{key}.json'
        if not tasks_path.exists():write(tasks_path,background(seed,config['prior']['episodes'],forbidden,config['prior']['kind']),True)
        tasks=read(tasks_path);prior_payload=dict(kind='prior',config=config,seed=seed,identity=identity,tasks=tasks)
        status=_enqueue(store,prior,candidate,prior_payload)
        if status!='completed':continue
        pf=store.directory/'jobs'/prior/'pretrained.pt';prior_source=dict(prior_file=str(pf),prior_sha=sha(pf))
        # Held-out ordinary shared tasks, allthree familiar context pairs.
        # Competence is measured after20 ordinary updates per unrelated task.
        cal_path=store.directory/'task_libraries'/f'{key}-competence.json'
        if not cal_path.exists():
            extra=forbidden+[p for r in tasks for p in r['paths']];raw=background(seed+900000,3,extra,'P2');cal=[]
            for i,pair in enumerate(['AB','AC','BC']):
                path=raw[i]['paths'][0];cal.append(dict(episode=1,paths=[path],kind='shared',pair=pair,updates=[dict(inner_update=k+1,block=k//5+1,context=pair[(k//5)%2],sequence=0) for k in range(20)]))
            write(cal_path,cal,True)
        for j,task in enumerate(read(cal_path)):
            id=f'competence-{key}-{j}';competence_ids.append(id);_enqueue(store,id,candidate,dict(kind='competence',config=config,seed=seed,identity=identity,tasks=[task],**prior_source))
        for task in bank['tasks']:
            id='target-'+fingerprint(dict(config=config,seed=seed,task=task,phase=phase))[:24];target_ids.append(id);_enqueue(store,id,candidate,dict(kind='target',config=config,seed=seed,identity=identity,task=task,phase=phase,**prior_source))
    return target_ids,competence_ids

def collect(store,ids):
    rows=[]
    for id in ids:
        status=store.db.execute('SELECT status FROM jobs WHERE id=?',(id,)).fetchone()[0]
        if status!='completed':return None
        path=store.directory/'jobs'/id/'evaluation.json'
        if path.exists():rows.append(read(path))
    return rows

def assessment(store,p,seeds):
    candidate=p['id'];control=control_config(store,p);ids,ci=ensure_jobs(store,candidate,p['config'],seeds);control_id='control-'+fingerprint(control)[:16];bid,bci=ensure_jobs(store,control_id,control,seeds)
    required=len(seeds)*len(read(store.directory/'development.json')['tasks'])
    if len(ids)!=required or len(bid)!=required:return None
    a=collect(store,ids);b=collect(store,bid)
    if a is None or b is None:return None
    manifest_snapshot(store,p,ids,ci,'development'+str(len(seeds)))
    comp=[];required_comp=(ci if p['config']['prior']['episodes'] else [])+(bci if control['prior']['episodes'] else [])
    for id in set(ci+bci):
        path=store.directory/'jobs'/id/'competence.json'
        if not path.exists():return None
        if id in required_comp:comp.append(read(path)['all_practiced_contexts_useful'])
    adequate=all(comp);feasible=all(r['development_feasible'] for r in a)
    frames=pd.DataFrame(a);means={k:float(frames[k].mean()) for k in ['D_A','D_B','A_to_B','B_to_A','sustained_cost','C_ce','C_accuracy','Mixed_ce','Mixed_accuracy']};means['familiar_fraction']=float(frames.familiar.mean())
    paired=[]
    for metric in ['D_A','D_B','A_to_B','B_to_A','sustained_cost','C_ce','Mixed_ce','NoContext_ce']:
        from experiments.meta_objective_balance.statistics import interval
        aa=pd.DataFrame(a).groupby('seed')[metric].mean().reindex(seeds);bb=pd.DataFrame(b).groupby('seed')[metric].mean().reindex(seeds);paired.append(dict(metric=metric,**interval((aa-bb).to_numpy(float),seeds)))
    for cue in ['C','NoContext','Mixed-average']:
        for metric in ['ce','accuracy']:
            key='static_view_'+cue+'_'+metric;native=cue.replace('-average','')+'_'+metric;aa=pd.DataFrame(a).groupby('seed')[native].mean().reindex(seeds);bb=pd.DataFrame(b).groupby('seed')[key].mean().reindex(seeds);paired.append(dict(metric=native,contrast='candidate-minus-control-checkpoint-static-quarter-view',**interval((aa-bb).to_numpy(float),seeds)))
    primary=p.get('ablation_primary',{'metric':'C_ce','direction':'min'});contrast=next((r for r in paired if r['metric']==primary.get('metric')),None);supported=bool(contrast and len(seeds)==6 and (contrast['ci_high']<0 if primary.get('direction')=='min' else contrast['ci_low']>0))
    return clean(dict(id=candidate,phase='development',seeds=list(seeds),tasks=len(a)//len(seeds),n_network_seeds=len(seeds),background_adequate=adequate,development_feasible=bool(feasible and adequate),classification='budget_inconclusive' if not adequate else 'joint_development_feasible' if feasible else 'partial_or_negative',ablation_supported=bool(supported and len(leaf_changes(control,p['config']))==1 and feasible and adequate),ablation_primary=primary,summary=means,paired_seed_intervals=paired,cohort=cohort(a,seeds),individual_results=a,matched_control_results=b,optimizer_calls=store.totals()['optimizer_steps'],claim='development only; late functional gate unassessed; no human mechanism inference'))

def advance(store):
    """Make local progress until one bounded agent call or queued compute boundary."""
    store.check();phase=store.get('phase') or 'propose';ctx={} if phase=='confirmation' else context(store)
    if phase=='propose':
        count=store.get('proposal_attempts') or 0
        if count>=store.limits['proposals']:store.control('stopped');return 'proposal ceiling'
        prior=store.get('agent_inflight')
        if prior and prior['phase']==phase:role=prior['role']
        else:role=['architecture','learning','experience','initialization'][count%4];store.set('proposal_attempts',count+1)
        r=invoke(store,role,'Propose one falsifiable experiment as JSON. Required fields: '+json.dumps(REQUIRED)+'. Config must use the complete registered model/prior/target schema. Also include novelty_justification and ablation_primary={metric,direction:min|max}. Do not execute code.',context=ctx);write(store.directory/'pending'/f'proposal-{count}.json',r,True);store.set('pending',r);store.set('phase','admit');return 'manual checkpoint after proposal'
    if phase=='admit':
        try:
            p=json.loads(store.get('pending')['text']);admit(store,p);store.set('active',p);store.set('phase','proposal_critic')
        except (ValueError,KeyError) as ex:store.event('proposal_rejected',str(ex));store.set('phase','propose')
        return 'local decision recorded'
    p=store.get('active')
    if phase=='proposal_critic':
        r=invoke(store,'critic','Review proposed change before any compute. Return JSON {accept:boolean, failed_prediction:string, explanations:[at least two], cheapest_discriminating_test:string, recommendation:string}. Do not change criteria.',kind='critic',context=ctx|dict(proposal=p));store.set('pending',r);store.set('phase','critic_admit');return 'manual checkpoint after critic'
    if phase=='critic_admit':
        r=json.loads(store.get('pending')['text']);write(store.directory/'candidates'/p['id']/'proposal_critic.json',r,True)
        if not r.get('accept') or len(r.get('explanations',[]))<2:
            store.db.execute("UPDATE nodes SET status='rejected' WHERE id=?",(p['id'],));store.set('phase','propose')
        else:store.set('phase','implementation_review')
        return 'critic decision recorded'
    if phase=='implementation_review':
        r=invoke(store,p['research_area'],'Review registered native config and ordinary-learning contract. Return JSON {valid:boolean, expected_changes:[...], tests:[...], risks:[...]}. Unsupported code must be quarantined, not executed.',kind='coding',context=ctx|dict(proposal=p));store.set('pending',r);store.set('phase','implementation_admit');return 'manual checkpoint after implementation review'
    if phase=='implementation_admit':
        r=json.loads(store.get('pending')['text']);write(store.directory/'candidates'/p['id']/'implementation_review.json',r,True)
        if not r.get('valid'):store.db.execute("UPDATE nodes SET status='quarantined' WHERE id=?",(p['id'],));store.set('phase','propose')
        else:store.set('development_tier',2);store.set('phase','evaluate')
        return 'config review recorded'
    if phase=='evaluate':
        n=store.get('development_tier') or 2;seeds=read(store.directory/'development.json')['seeds'][:n];r=assessment(store,p,seeds)
        if r is None:return 'compute queued or pending'
        store.result(p['id']+f'-dev{n}',r);write(store.directory/'candidates'/p['id']/f'development{n}.json',r,True)
        if r['development_feasible'] and n==2:store.set('development_tier',6);return 'unchanged candidate advanced to remaining development seeds'
        store.set('latest_result',r);store.set('phase','result_critic');return 'development assessment saved'
    if phase=='result_critic':
        r=invoke(store,'critic','Identify strongest exact behavioral prediction failure, give two competing explanations and the smallest discriminating follow-up. Return JSON {failed_prediction,explanations,cheapest_discriminating_test,recommendation}. A budget-inconclusive run cannot refute its hypothesis.',kind='critic',context=ctx|dict(proposal=p,result=result_view(store.get('latest_result'))));store.set('pending',r);store.set('phase','decision');return 'manual checkpoint after result criticism'
    if phase=='decision':
        criticism=json.loads(store.get('pending')['text']);write(store.directory/'candidates'/p['id']/'result_critic.json',criticism,True);store.set('phase','coordinator_review');return 'failure explanation retained'
    if phase=='coordinator_review':
        r=invoke(store,'coordinator','Return JSON {decision:retain|abandon|revise|confirm,reason,next_hypothesis}. Confirmation requires replicated development and matched ablation. Do not alter the thresholds, code or budget.',kind='coordinator',context=ctx|dict(proposal=p,result=result_view(store.get('latest_result'))));store.set('pending',r);store.set('phase','coordinator_decision');return 'manual checkpoint after coordinator review'
    if phase=='coordinator_decision':
        decision=json.loads(store.get('pending')['text']);r=store.get('latest_result');write(store.directory/'candidates'/p['id']/'decision.json',decision,True)
        if decision.get('decision')=='confirm' and r['development_feasible'] and r['ablation_supported'] and r['n_network_seeds']==6:
            from research_search.evaluation.confirmation import commit
            control=control_config(store,p);plan=dict(frozen=True,development_qualified=True,ablation_supported=True,config_hash=fingerprint(p['config']),matched_control_config_hash=fingerprint(control),family=p['id'],all_confirmation_tasks=True,seeds='all6 held-out',results_not_exposed_to_agents=True)
            commit(store,p['id'],read(PACKAGE/'audit/evaluator_seal.json')['runner_hash'],plan);store.set('phase','confirmation');return 'once-only confirmation plan committed'
        if decision.get('decision')=='revise':store.repair(p['id'],scientific=True)
        store.db.execute("UPDATE nodes SET status=? WHERE id=?",('abandoned' if decision.get('decision')=='abandon' else 'retained',p['id']));store.set('phase','propose');return 'branch closed or retained; revision requires new ID'
    if phase=='confirmation':
        seeds=read(store.directory/'sealed/confirmation.json')['seeds'];ids,ci=ensure_jobs(store,p['id'],p['config'],seeds,'confirmation');control=control_config(store,p);bid,bci=ensure_jobs(store,'control-'+fingerprint(control)[:16],control,seeds,'confirmation');required=6*len(read(store.directory/'sealed/confirmation.json')['tasks'])
        if len(ids)!=required or len(bid)!=required:return 'confirmation compute queued'
        result=collect(store,ids);matched=collect(store,bid)
        if result is None or matched is None:return 'confirmation compute pending'
        write(store.directory/'sealed'/f"{p['id']}-results.json",dict(candidate=result,matched_control=matched),True);store.db.execute("UPDATE confirmations SET status='completed' WHERE family=?",(p['id'],));store.db.execute("UPDATE nodes SET status='confirmation_completed' WHERE id=?",(p['id'],));store.set('phase','complete');store.control('stopped');return 'confirmation sealed; campaign stopped with no further agent feedback'
    raise ValueError('Unknown durable phase '+phase)
